def isValid(word: str) -> bool:
    # Check length condition
    if len(word) < 3:
        return False

    has_vowel = False
    has_consonant = False

    vowels = set('aeiouAEIOU')

    for ch in word:
        # Check that character is alphanumeric (digits or letters)
        if not ch.isalnum():
            return False

        # If it's a letter, classify as vowel or consonant
        if ch.isalpha():
            if ch in vowels:
                has_vowel = True
            else:
                has_consonant = True

    # All conditions must be satisfied
    return has_vowel and has_consonant

