def make_palindrome(s: str) -> str:
    s = list(s)
    n = len(s)
    left, right = 0, n - 1

    while left < right:
        if s[left] != s[right]:
            # Change the larger character to the smaller one for lexicographically smallest
            if s[left] > s[right]:
                s[left] = s[right]
            else:
                s[right] = s[left]
        left += 1
        right -= 1

    return "".join(s)
