def getSmallestString(s: str) -> str:
    n = len(s)
    s = list(s)

    # Find the first non-'a' character to start the operation
    start = 0
    while start < n and s[start] == 'a':
        start += 1

    if start == n:
        # The string consists of all 'a's, change the last 'a' to 'z'
        s[-1] = 'z'
        return ''.join(s)

    # Apply operation from start until we hit an 'a' (or end)
    end = start
    while end < n and s[end] != 'a':
        s[end] = chr(ord(s[end]) - 1)
        end += 1

    return ''.join(s)
