from functools import lru_cache

def number_of_beautiful_integers(low: int, high: int, k: int) -> int:
    def count_up_to(x: int) -> int:
        s = list(map(int, str(x)))
        n = len(s)

        @lru_cache(maxsize=None)
        def dfs(pos: int, tight: bool, leading_zero: bool, balance: int, rem: int) -> int:
            if pos == n:
                # valid number must have started, equal even/odd digits, and divisible by k
                if not leading_zero and balance == 0 and rem == 0:
                    return 1
                return 0

            limit = s[pos] if tight else 9
            total = 0
            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_leading_zero = leading_zero and (d == 0)

                if new_leading_zero:
                    # still building leading zeros, balance and remainder unchanged
                    total += dfs(pos + 1, new_tight, True, balance, rem)
                else:
                    # update balance: even digit -> +1, odd digit -> -1
                    new_balance = balance + (1 if d % 2 == 0 else -1)
                    new_rem = (rem * 10 + d) % k
                    total += dfs(pos + 1, new_tight, False, new_balance, new_rem)

            return total

        return dfs(0, True, True, 0, 0)

    return count_up_to(high) - count_up_to(low - 1)
