import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().splitlines()
    H, W = map(int, input_data[0].split())
    grid = [list(row) for row in input_data[1:1+H]]

    # Count of remaining cookies per row/column
    row_count = [W] * H
    col_count = [H] * W

    # Track distinct colors left in each row/col
    row_colors = [set(grid[i][j] for j in range(W)) for i in range(H)]
    col_colors = [set(grid[i][j] for i in range(H)) for j in range(W)]

    removed = [[False] * W for _ in range(H)]

    queue = deque()

    # Initialize with rows and columns that can be marked
    for i in range(H):
        if row_count[i] >= 2 and len(row_colors[i]) == 1:
            for j in range(W):
                if not removed[i][j]:
                    removed[i][j] = True
                    queue.append((i, j))

    for j in range(W):
        if col_count[j] >= 2 and len(col_colors[j]) == 1:
            for i in range(H):
                if not removed[i][j]:
                    removed[i][j] = True
                    queue.append((i, j))

    while queue:
        # Process removed cookies: update counts and color sets
        while queue:
            i, j = queue.popleft()

            # Update row i
            row_count[i] -= 1
            # Recompute row colors if needed
            if row_count[i] >= 2:
                # Check if all remaining in this row are the same
                colors = set()
                for col in range(W):
                    if not removed[i][col]:
                        colors.add(grid[i][col])
                row_colors[i] = colors

            # Update column j
            col_count[j] -= 1
            if col_count[j] >= 2:
                colors = set()
                for row in range(H):
                    if not removed[row][j]:
                        colors.add(grid[row][j])
                col_colors[j] = colors

        # Now find new rows/columns to mark
        for i in range(H):
            if row_count[i] >= 2 and len(row_colors[i]) == 1:
                for j in range(W):
                    if not removed[i][j]:
                        removed[i][j] = True
                        queue.append((i, j))

        for j in range(W):
            if col_count[j] >= 2 and len(col_colors[j]) == 1:
                for i in range(H):
                    if not removed[i][j]:
                        removed[i][j] = True
                        queue.append((i, j))

    # Count remaining
    remaining = sum(1 for i in range(H) for j in range(W) if not removed[i][j])
    print(remaining)

if __name__ == "__main__":
