def minOperations(word: str) -> int:
    n = len(word)
    # dp[i][c] = min ops to fix word[0..i] with word[i] == chr(ord('a')+c)
    INF = 10**9
    dp = [[INF] * 26 for _ in range(n)]

    for c in range(26):
        dp[0][c] = 1 if chr(ord('a')+c) != word[0] else 0

    for i in range(1, n):
        for c in range(26):
            # cost to change this position
            cost = 1 if chr(ord('a')+c) != word[i] else 0
            best_prev = INF
            for p in range(26):
                if abs(p - c) > 1:  # not almost-equal
                    best_prev = min(best_prev, dp[i-1][p])
            dp[i][c] = cost + best_prev

    return min(dp[n-1])
