from collections import Counter
from typing import List

def countSubMultisets(nums: List[int], l: int, r: int) -> int:
    MOD = 10**9 + 7
    count = Counter(nums)
    dp = [0] * (r + 1)
    dp[0] = 1

    for val, freq in count.items():
        if val == 0:
            continue
        for remainder in range(r + 1):
            if dp[remainder] == 0:
                continue
            for k in range(1, freq + 1):
                s = remainder + k * val
                if s > r:
                    break
                dp[s] = (dp[s] + dp[remainder]) % MOD

    zeros = count.get(0, 0)
    total = sum(dp[l:r+1]) % MOD
    if zeros > 0:
        total = (total * (zeros + 1)) % MOD
    return total
