```python
def longest_common_suffix(container, query):
    # Trie node: children dict, best_index, best_len
    class Node:
        __slots__ = ('children', 'best_idx', 'best_len')
        def __init__(self):
            self.children = {}
            self.best_idx = -1
            self.best_len = float('inf')

    root = Node()

    # Insert each container word (reversed) into the trie
    for idx, word in enumerate(container):
        rev = word[::-1]
        node = root
        # Update root with empty suffix
        if len(word) < node.best_len or (len(word) == node.best_len and idx < node.best_idx):
            node.best_len = len(word)
            node.best_idx = idx
        # Insert characters
        for ch in rev:
            if ch not in node.children:
                node.children[ch] = Node()
            node = node.children[ch]
            # Update current node with this word
            if len(word) < node.best_len or (len(word) == node.best_len and idx < node.best_idx):
                node.best_len = len(word)
                node.best_idx = idx

    # Process queries
    ans = []
    for word in query:
        rev = word[::-1]
        node = root
        # Traverse as deep as possible
        for ch in rev:
            if ch in node.children:
                node = node.children[ch]
            else:
                break
        ans.append(node.best_idx)
    return ans
