import sys

def is_possible(s: str, t: str) -> bool:
    """Return True if s could be the original string T given that the
       received string is t, under the conditions:
         - s == t,
         - t = s with one insertion,
         - t = s with one deletion,
         - t = s with one substitution.
    """
    len_s, len_t = len(s), len(t)
    # Length difference cannot exceed 1
    if abs(len_s - len_t) > 1:
        return False

    # Equal length: must be equal or exactly one substitution
    if len_s == len_t:
        diff = 0
        for a, b in zip(s, t):
            if a != b:
                diff += 1
                if diff > 1:
                    return False
        return True  # diff == 0 or diff == 1

    # t is longer by 1 -> insertion into s
    if len_s + 1 == len_t:
        i = j = 0
        # find first mismatch
        while i < len_s and j < len_t:
            if s[i] == t[j]:
                i += 1
                j += 1
            else:
                j += 1  # skip the extra character in t
                break
        # compare the remaining parts
        while i < len_s and j < len_t:
            if s[i] != t[j]:
                return False
            i += 1
            j += 1
        return True

    # len_s == len_t + 1 -> deletion from s
    i = j = 0
    while i < len_s and j < len_t:
        if s[i] == t[j]:
            i += 1
            j += 1
        else:
            i += 1  # skip the deleted character in s
            break
    while i < len_s and j < len_t:
        if s[i] != t[j]:
            return False
        i += 1
        j += 1
    return True


