def prime_pairs(n):
    # Sieve of Eratosthenes to find primes up to n
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n+1, i):
                is_prime[j] = False

    result = []
    # x <= y and x + y = n  =>  x <= n/2
    for x in range(2, n//2 + 1):
        y = n - x
        if is_prime[x] and is_prime[y]:
            result.append([x, y])
    return result
