def maximize_gold(n: int, offers: list[list[int]]) -> int:
    # Group offers by their ending house
    end_offers = [[] for _ in range(n)]
    for start, end, gold in offers:
        end_offers[end].append((start, gold))

    dp = [0] * n
    for i in range(n):
