            # Count consecutive pairs
            pairs = 0
            for k in range(len(substring) - 1):
                if substring[k] == substring[k + 1]:
                    pairs += 1

            # A semi-repetitive string has at most one consecutive pair
            if pairs <= 1:
                max_len = max(max_len, len(substring))

