def minimum_string(a: str, b: str, c: str) -> str:
    def merge(s1: str, s2: str) -> str:
        """Return the shortest string that contains both s1 and s2, with s1 before s2."""
        if s1 in s2:
            return s2
        if s2 in s1:
            return s1
        max_overlap = 0
        for i in range(1, min(len(s1), len(s2)) + 1):
            if s1[-i:] == s2[:i]:
                max_overlap = i
        return s1 + s2[max_overlap:]

    def merge_three(x: str, y: str, z: str) -> str:
        return merge(merge(x, y), z)

    import itertools
    best = None
    for perm in itertools.permutations([a, b, c]):
        candidate = merge_three(*perm)
        if best is None or len(candidate) < len(best) or (len(candidate) == len(best) and candidate < best):
            best = candidate
    return best
