def punishmentNumber(n: int) -> int:
    def can_partition(s, target):
        if not s and target == 0:
            return True
        if target < 0:
            return False

        for i in range(1, len(s) + 1):
            left = int(s[:i])
            if can_partition(s[i:], target - left):
                return True
        return False

    total_punishment = 0
    for i in range(1, n + 1):
        sq = i * i
        if can_partition(str(sq), i):
            total_punishment += sq

    return total_punishment
