def number_of_adjacent_elements(n, queries):
    """
    Returns an array answer where answer[i] is the number of adjacent elements
    with the same non-zero color after the i-th query.
    """
    nums = [0] * n          # current colors, 0 means uncolored
    ans = []                # to store answers after each query
    curr = 0                # current count of adjacent equal non-zero pairs

    for idx, col in queries:
        old = nums[idx]     # color at index before update
        if old != col:
            # Check left neighbour (idx-1, idx)
            if idx > 0:
                left = nums[idx - 1]
                if left != 0 and left == old:
                    curr -= 1
                if left != 0 and left == col:
                    curr += 1
            # Check right neighbour (idx, idx+1)
            if idx < n - 1:
                right = nums[idx + 1]
                if right != 0 and right == old:
                    curr -= 1
                if right != 0 and right == col:
                    curr += 1
            nums[idx] = col   # apply the update

        ans.append(curr)      # record the current count

    return ans
