def minimumCost(source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
    INF = 10**18
    # map letters to indices 0..25
    dist = [[INF] * 26 for _ in range(26)]
    for i in range(26):
        dist[i][i] = 0

    # add edges (keep minimum cost for each pair)
    for o, ch, c in zip(original, changed, cost):
        u = ord(o) - 97
        v = ord(ch) - 97
        if c < dist[u][v]:
            dist[u][v] = c

    # Floyd-Warshall for all-pairs shortest paths
    for k in range(26):
        dk = dist[k]
        for i in range(26):
            di = dist[i]
            dik = di[k]
            if dik == INF:
                continue
            # inner loop
            for j in range(26):
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    total = 0
    for s, t in zip(source, target):
        u = ord(s) - 97
        v = ord(t) - 97
        if dist[u][v] == INF:
            return -1
        total += dist[u][v]

    return total
