def paintWalls(cost, time):
    n = len(cost)
    INF = 10**18
    dp = [INF] * (n + 1)
    dp[0] = 0
    for c, t in zip(cost, time):
        coverage = t + 1  # each paid wall also gives one free wall slot
        for j in range(n, -1, -1):
            if dp[j] != INF:
                new_j = min(n, j + coverage)  # cap at n
                if dp[new_j] > dp[j] + c:
                    dp[new_j] = dp[j] + c
