We need to try placing subsets of the tiles onto the grid, checking if they can exactly cover it.  
Because N ≤ 7 and H,W ≤ 10, a backtracking search over placements is feasible.

Below is the Python implementation:

```python
import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    H = int(next(it))
    W = int(next(it))
    tiles = []
    for _ in range(N):
        a = int(next(it))
        b = int(next(it))
        tiles.append((a, b))

    # We'll attempt to cover the grid using a subset of tiles.
    # Use backtracking: try placing tiles in empty cells.

    grid = [[0] * W for _ in range(H)]
    used = [False] * N

    def can_place(grid, h, w, tile_h, tile_w):
        if h + tile_h > H or w + tile_w > W:
            return False
        for i in range(tile_h):
            for j in range(tile_w):
                if grid[h + i][w + j] != 0:
                    return False
        return True

    def place(grid, h, w, tile_h, tile_w, tile_idx):
        for i in range(tile_h):
            for j in range(tile_w):
                grid[h + i][w + j] = tile_idx

    def remove(grid, h, w, tile_h, tile_w):
        for i in range(tile_h):
            for j in range(tile_w):
                grid[h + i][w + j] = 0

    def backtrack(grid):
        # find first empty cell
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    for idx in range(N):
                        if used[idx]:
                            continue
                        a, b = tiles[idx]
                        for tile_h, tile_w in [(a, b), (b, a)]:
                            if can_place(grid, i, j, tile_h, tile_w):
                                place(grid, i, j, tile_h, tile_w, idx+1)
                                used[idx] = True
                                if backtrack(grid):
                                    return True
                                remove(grid, i, j, tile_h, tile_w)
                                used[idx] = False
                    return False
        return True  # no empty cell means covered

    result = backtrack(grid)
    print("Yes" if result else "No")

if __name__ == "__main__":
    solve()
```

