def canSortArray(nums):
    # Group numbers by number of set bits while preserving relative order
    groups = []
    current_group = []
    current_bits = None

    for num in nums:
        bits = num.bit_count()
        if bits == current_bits:
            current_group.append(num)
        else:
            if current_group:
                groups.append(current_group)
            current_group = [num]
            current_bits = bits
    if current_group:
        groups.append(current_group)

    # Sort within each group
    for group in groups:
        group.sort()

    # Flatten and check if sorted
    sorted_candidate = [num for group in groups for num in group]
    return sorted_candidate == sorted(nums)
