from typing import List

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x: int, y: int) -> None:
        xroot = self.find(x)
        yroot = self.find(y)
        if xroot == yroot:
            return
        if self.rank[xroot] < self.rank[yroot]:
            self.parent[xroot] = yroot
        elif self.rank[xroot] > self.rank[yroot]:
            self.parent[yroot] = xroot
        else:
            self.parent[yroot] = xroot
            self.rank[xroot] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n <= 1:
        return True

    max_val = max(nums)
    # Sieve to compute smallest prime factor (spf) for each number up to max_val
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val ** 0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    uf = UnionFind(n)
    # Map from prime to the first index that introduced this prime
    prime_to_index = {}

    for i, num in enumerate(nums):
        if num == 1:
            continue  # 1 has no prime factors and cannot connect to anything

        # Factorize num into distinct primes
        x = num
        primes = set()
        while x > 1:
            p = spf[x]
            primes.add(p)
            while x % p == 0:
                x //= p

        # For each distinct prime, union current index with the prime's representative
        for p in primes:
            if p in prime_to_index:
                uf.union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    # After all unions, check that all indices belong to the same component
    root = uf.find(0)
    for i in range(1, n):
        if uf.find(i) != root:
            return False
    return True
