import sys

MOD = 998244353

def solve() -> None:
    S = sys.stdin.readline().strip()
    n = len(S)
    # dp[b] = number of ways for processed prefix with current balance b
    dp = [0] * (n + 1)
    dp[0] = 1

    for ch in S:
        ndp = [0] * (n + 1)
        if ch == '(':
            for b in range(n):
                if dp[b]:
                    ndp[b + 1] = (ndp[b + 1] + dp[b]) % MOD
        elif ch == ')':
            for b in range(1, n + 1):
                if dp[b]:
                    ndp[b - 1] = (ndp[b - 1] + dp[b]) % MOD
        else:  # ch == '?'
            for b in range(n + 1):
                if dp[b] == 0:
                    continue
                # replace with '('
                if b + 1 <= n:
                    ndp[b + 1] = (ndp[b + 1] + dp[b]) % MOD
