def min_mountain_sum(nums):
    n = len(nums)
    min_sum = float('inf')
    for j in range(1, n - 1):
        # Find smallest nums[i] on left that is < nums[j]
        left_min = float('inf')
        for i in range(j):
            if nums[i] < nums[j]:
                left_min = min(left_min, nums[i])
