def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute adjacency: can i be followed by j?
    adj = [[False]*n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                adj[i][j] = True

    # dp[mask][i] : number of permutations using mask ending with i
    dp = [[0]*n for _ in range(1<<n)]

    # base: single element permutations
    for i in range(n):
        dp[1<<i][i] = 1

    # iterate over all masks
    for mask in range(1<<n):
        for i in range(n):
            if not (mask & (1<<i)):  # i not in mask
                continue
            if dp[mask][i] == 0:
                continue
            # try to append j not in mask
            for j in range(n):
                if mask & (1<<j):  # already used
                    continue
                if adj[i][j]:
                    dp[mask | (1<<j)][j] = (dp[mask | (1<<j)][j] + dp[mask][i]) % MOD

    full_mask = (1<<n) - 1
    ans = sum(dp[full_mask][i] for i in range(n)) % MOD
    return ans
