    # Track column constraints for each letter
    col_seen = [set() for _ in range(N)]

    def backtrack(row):
        if row == N:
            # verify column topmost constraints and each column has exactly one A, B, C
            for col in range(N):
                top_char = None
                letters = set()
                for r in range(N):
                    ch = grid[r][col]
                    if ch != ".":
                        if top_char is None:
                            top_char = ch
                        letters.add(ch)
                if top_char != C[col]:
                    return False
                if letters != {"A", "B", "C"}:
                    return False
            return True

        # For current row, we need exactly one A, one B, one C, rest empty
        positions = list(range(N))
        from itertools import permutations

        # We assign the three letters to three distinct columns
        for cols in permutations(positions, 3):
            # Check column constraints so far
            valid_assignment = True
            for letter, col in zip(["A", "B", "C"], cols):
                if letter in col_seen[col]:
                    valid_assignment = False
                    break
            if not valid_assignment:
                continue

            # Also check leftmost constraint for this row
            min_col = min(cols)
            if R[row] != grid[row][min_col] and grid[row][min_col] == ".":
                pass
            else:
                continue  # leftmost must match R[row], so ensure none placed before min_col and min_col gets R[row]

            # Actually we must place R[row] at the leftmost among the three
            if R[row] not in ["A", "B", "C"]:
                continue
            # The leftmost used column must have R[row]
            # Reorder assignment to put R[row] at min column
            letter_col_map = {}
            for letter, col in zip(["A", "B", "C"], cols):
                letter_col_map[letter] = col
            min_col_pos = min(cols)
            if letter_col_map[R[row]] != min_col_pos:
                continue

            # Now place letters
            for letter, col in zip(["A", "B", "C"], cols):
                grid[row][col] = letter
                col_seen[col].add(letter)

            if backtrack(row + 1):
                return True

            # Undo
            for letter, col in zip(["A", "B", "C"], cols):
                grid[row][col] = "."
                col_seen[col].remove(letter)

        return False

    if backtrack(0):
        print("Yes")
        for r in range(N):
            print("".join(grid[r]))
    else:
