def max_jumps(nums, target):
    n = len(nums)
    # dp[i] = max jumps to reach index i from 0; -1 means unreachable
    dp = [-1] * n
    dp[0] = 0  # starting point

    for i in range(n):
        if dp[i] == -1:
            continue  # cannot reach i, skip
        for j in range(i + 1, n):
            diff = abs(nums[j] - nums[i])
            if diff <= target:
                # jump from i to j is allowed
                if dp[j] < dp[i] + 1:
                    dp[j] = dp[i] + 1
    return dp[n - 1]
```

