def max_good_subarray_sum(nums, k):
    n = len(nums)
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + nums[i]

    # map from value to minimum prefix sum seen so far (prefix before the index)
    min_prefix = {}
    ans = float('-inf')

    for j in range(n):
        val = nums[j]
        # check possible start values
        for target in (val - k, val + k):
            if target in min_prefix:
                candidate = pref[j+1] - min_prefix[target]
                if candidate > ans:
                    ans = candidate
        # update dictionary with current element as a potential start for future subarrays
        # prefix sum before index j
        current_prefix = pref[j]
        if val in min_prefix:
            if current_prefix < min_prefix[val]:
                min_prefix[val] = current_prefix
        else:
            min_prefix[val] = current_prefix

    return int(ans) if ans != float('-inf') else 0
